/* Upper bound for the scroll speed accumulator. speed is a uint8 accelerated
 * by speed += acc every frame; left unbounded it can wrap to 0 (progress
 * stalls -> infinite loop) or grow large enough that offset += speed overshoots
 * the 128/64 terminal offset and wraps the uint8 counter past it. Capping speed
 * to 64 keeps offset + speed <= 191 (< 256, no wrap) for both the 128-wide and
 * 64-tall scrolls while always leaving speed >= 1. */
#define ANIM_SPEED_MAX 64u

