/*
 *  @brief      Animation Screen Switch Horizontal Scroll
 *  @since      v1.0
 *  Sample usage:       Animation_Screen_Switch_Horizontal_Scroll();
 */
void Animation_Screen_Switch_Horizontal_Scroll_Array(const Coord *src, const int srcLen, const Coord *dst, const int dstLen, uint8 direction, uint8 speed, uint8 acc)
{
    // This function is a wrapper for Animation_Screen_Switch_Horizontal_Scroll
    uint8 animation_flag = 0; // Animation flag to indicate if the animation is running
    uint8 animation[64][16] = {0x00}; // 64 rows, 128 columns

    // src and dst should not be NULL
    if (src == NULL || dst == NULL) {
        return; // Invalid input, exit the function
    }

    if (speed == 0) speed = 1; // guarantee progress; speed==0 && acc==0 would loop forever

    if (direction == 0) { // Left to right
        // Implement left to right scroll logic
        uint8 x_offset = 0; // Starting offset for the scroll
        while (animation_flag == 0) {
            // Clear the animation array
            memset(animation, 0x00, sizeof(animation));
            // Check current offset against the source and destination lengths
            if (x_offset >= 128) {
                x_offset = 128; // Reset offset if it exceeds bounds
                animation_flag = 1;
            }
            // Draw the source image at the current offset
            for (int i = 0; i < srcLen; i++) {
                uint8 x = src[i].x + x_offset;
                uint8 y = src[i].y;
                if (x < 128 && y < 64) { // Ensure within bounds
                    animation[y][x >> 3] |= (0x01 << (7 - (x & 0x07))); // Set the pixel in the animation array
                }
            }
            // Draw the destination image at the current offset
            for (int i = 0; i < dstLen; i++) {
                uint8 x = dst[i].x + x_offset;
                uint8 y = dst[i].y;
                if (x < 128) {
                    continue; // Skip if x is out of bounds
                } else {
                    x -= 128; // Adjust for the offset
                }
                if (x < 128 && y < 64) { // Ensure within bounds
                    animation[y][x >> 3] |= (0x01 << (7 - (x & 0x07))); // Set the pixel in the animation array
                }
            }
            // Display the animation frame (this function should be defined to handle the display logic)
            Oled_I2C_Draw_Picture_128x64((const uint8*)animation);
            // Update the offset for the next frame
            x_offset += speed; // Increment the offset by the speed
            // Accelerate, capped at ANIM_SPEED_MAX so speed cannot wrap the
            // uint8 counter to 0 or overshoot/wrap the terminal offset.
            if (acc > 0) {
                speed = (speed + acc > ANIM_SPEED_MAX) ? (uint8)ANIM_SPEED_MAX : (uint8)(speed + acc);
            }
            // Delay for a short period to control the frame rate
            //DWT_Delay_ms(10); // Adjust delay based on speed
        }
    }
    else if (direction == 1) { // Right to left
        // Implement right to left scroll logic
        uint8 x_offset = 128; // Starting offset for the scroll
        while (animation_flag == 0) {
            // Clear the animation array
            memset(animation, 0x00, sizeof(animation));
            // Check current offset against the source and destination lengths
            if (x_offset <= 0) {
                x_offset = 0; // Reset offset if it goes below zero
                animation_flag = 1;
            }
            // Draw the source image at the current offset
            for (int i = 0; i < srcLen; i++) {
                uint8 x = src[i].x + x_offset;
                uint8 y = src[i].y;
                if (x < 128) {
                    continue; // Skip if x is out of bounds
                } else {
                    x -= 128; // Adjust for the offset
                }
                if (x < 128 && y < 64) { // Ensure within bounds
                    animation[y][x >> 3] |= (0x01 << (7 - (x & 0x07))); // Set the pixel in the animation array
                }
            }
            // Draw the destination image at the current offset
            for (int i = 0; i < dstLen; i++) {
                uint8 x = dst[i].x + x_offset;
                uint8 y = dst[i].y;
                if (x < 128 && y < 64) { // Ensure within bounds
                    animation[y][x >> 3] |= (0x01 << (7 - (x & 0x07))); // Set the pixel in the animation array
                }
            }
            // Display the animation frame (this function should be defined to handle the display logic)
            Oled_I2C_Draw_Picture_128x64((const uint8*)animation);
            // Update the offset for the next frame
            if(x_offset < speed) {
                x_offset = 0; // Reset offset if it goes below zero
            } else {
                x_offset -= speed; // Decrement the offset by the speed
            }
            // Accelerate, capped at ANIM_SPEED_MAX so speed cannot wrap the
            // uint8 counter to 0 (which would stall the countdown to zero).
            if (acc > 0) {
                speed = (speed + acc > ANIM_SPEED_MAX) ? (uint8)ANIM_SPEED_MAX : (uint8)(speed + acc);
            }
            // Delay for a short period to control the frame rate
            //DWT_Delay_ms(10); // Adjust delay based on speed
        }
    }
}

